using System.Security.Claims;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.Components.Web;
using sv_6446b41b67fe450c8f48725a53a6f8cf.Client;

namespace sv_6446b41b67fe450c8f48725a53a6f8cf.Auth;

/// <summary>
/// Server-side AuthenticationStateProvider that simulates a hardcoded user
/// and persists the auth state so the WebAssembly client can pick it up.
/// </summary>
public sealed class ServerAuthenticationStateProvider : AuthenticationStateProvider, IDisposable
{
    private readonly PersistentComponentState _persistentComponentState;
    private readonly PersistingComponentStateSubscription _subscription;

    private static readonly UserInfo HardcodedUser = new()
    {
        Email = "bob@example.com",
        Roles = new[] { "User", "Editor" }
    };

    private Task<AuthenticationState>? _authenticationStateTask;

    public ServerAuthenticationStateProvider(PersistentComponentState persistentComponentState)
    {
        _persistentComponentState = persistentComponentState;
        _subscription = _persistentComponentState.RegisterOnPersisting(OnPersistingAsync, RenderMode.InteractiveWebAssembly);
    }

    public override Task<AuthenticationState> GetAuthenticationStateAsync()
    {
        if (_authenticationStateTask is null)
        {
            var claims = new List<Claim>
            {
                new(ClaimTypes.Name, HardcodedUser.Email),
                new(ClaimTypes.Email, HardcodedUser.Email),
                new(ClaimTypes.Role, "User"),
                new(ClaimTypes.Role, "Editor"),
            };

            var identity = new ClaimsIdentity(claims, "Hardcoded");
            var user = new ClaimsPrincipal(identity);
            _authenticationStateTask = Task.FromResult(new AuthenticationState(user));
        }

        return _authenticationStateTask;
    }

    private async Task OnPersistingAsync()
    {
        var authState = await GetAuthenticationStateAsync();
        if (authState.User.Identity?.IsAuthenticated == true)
        {
            _persistentComponentState.PersistAsJson(nameof(UserInfo), HardcodedUser);
        }
    }

    public void Dispose()
    {
        _subscription.Dispose();
    }
}

