using System.Security.Claims;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.Components.Server;
using Microsoft.AspNetCore.Components.Web;
using sv_6446b41b67fe450c8f48725a53a6f8cf.Client;

namespace sv_6446b41b67fe450c8f48725a53a6f8cf.Auth;

/// <summary>
/// Server-side AuthenticationStateProvider that simulates a hardcoded user
/// and persists the auth state so the WebAssembly client can pick it up.
/// </summary>
public sealed class ServerAuthenticationStateProvider : ServerAuthenticationStateProvider<UserInfo>
{
    private static readonly UserInfo HardcodedUser = new()
    {
        Email = "bob@example.com",
        Roles = new[] { "User", "Editor" }
    };

    protected override Task<AuthenticationState> GetAuthenticationStateAsync()
    {
        var claims = new List<Claim>
        {
            new(ClaimTypes.Name, HardcodedUser.Email),
            new(ClaimTypes.Email, HardcodedUser.Email),
            new(ClaimTypes.Role, "User"),
            new(ClaimTypes.Role, "Editor"),
        };

        var identity = new ClaimsIdentity(claims, "Hardcoded");
        var user = new ClaimsPrincipal(identity);

        return Task.FromResult(new AuthenticationState(user));
    }

    protected override UserInfo? MapToClientModel(AuthenticationState authenticationState)
    {
        if (authenticationState.User.Identity?.IsAuthenticated != true)
            return null;

        return HardcodedUser;
    }
}

